/// 🪪️ Evidence copied only from the frame's actually granted construction witness.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct NativeReceivingConstructionBinding{action:OriginalConstructionActionIdentity,work:OriginalWorkBindingIdentity,work_action:OriginalWorkActionIdentity,source:Option<OriginalSourceTurnIdentity>,grant:RetainedCloneGrant}
impl NativeReceivingConstructionBinding{
 /// 🪪️ Derives the opaque relay only from the genuine construction witness and its actual Work effect.
 pub fn from_original_effect(proof:&OriginalConstructionEffectProof,effect:&RetainedAllocationEffect<'_>)->Result<Self,ValueError>{let work=proof.work_binding();let source=proof.source_turn();if source.is_none()||!proof.matches_effect(effect){return Err(ValueError::invariant("original construction effect witness changed"))}Ok(Self{action:proof.identity(),work,work_action:effect.work_identity().action_identity(),source,grant:effect.grant()})}
 pub fn action(&self)->OriginalConstructionActionIdentity{self.action}
 pub fn work(&self)->OriginalWorkBindingIdentity{self.work}
 pub fn work_action(&self)->OriginalWorkActionIdentity{self.work_action}
 pub fn source(&self)->Option<OriginalSourceTurnIdentity>{self.source}
 pub fn matches_effect(&self,effect:&RetainedAllocationEffect<'_>)->bool{effect.construction_action()==Some(self.action)&&self.source.is_some()&&self.source==effect.work_source_turn()&&self.grant==effect.grant()&&self.work_action==effect.work_identity().action_identity()&&self.work.matches_effect(effect)}
}
/// 🧵️ Lends the same native receiving authorities without transferring their producers or budgets.
pub trait NativeReceivingEffectHost{
 fn original_work(&mut self)->OriginalWorkBorrow<'_>;
 fn begin_construction(&mut self,demand:RetirementDemand,action:&mut Option<OriginalConstructionAction>)->Result<OriginalConstructionIssuerIdentity,ValueError>;
 fn work_issuer(&self)->Option<OriginalWorkIssuerIdentity>;
 fn construction(&mut self)->Result<OriginalConstructionLoan<'_>,ValueError>;
 fn publish_receiving_completion(&mut self,receiving:&mut OriginalReceivingPrimary,payout:&OriginalConstructionAction,proof:&OriginalWorkActionProof)->Result<bool,ValueError>;
 fn checkpoint(&mut self)->Result<(),ValueError>;
 fn has_retirement(&self)->bool;
 fn observe_retirement(&mut self)->Result<(),ValueError>;
 fn pending_work(&self)->u64;
 fn has_pending_work(&self)->bool;
 fn work_quote_pending(&self)->bool;
 fn validate_work_proof(&self,proof:&OriginalWorkActionProof,actual:u128)->Result<bool,ValueError>;
 fn prepare_allocation_effect(&mut self,bytes:usize,actual:&Option<usize>,state:&mut Option<NativeDecodeAllocationProgress>,cancellable:bool)->NativeDecodeAllocationAdmission;
 fn recover_allocation_callback(&mut self,state:&mut NativeDecodeAllocationProgress)->Result<bool,ValueError>;
 fn settle_allocation_progress(&mut self,state:&mut NativeDecodeAllocationProgress,actual:Option<usize>)->Result<bool,ValueError>;
}
