 pub fn has_no_retained_custody(&self)->bool{self.phase==NativeReceivingEffectPhase::Empty&&self.ack_identity.is_none()&&!self.ready&&!self.unallocated_started&&!self.work_settled&&!self.work_commit_pending&&!self.retiring&&self.actual_work==0&&self.work_reported==0&&self.settled_progress==RetainedCloneProgress::default()&&self.producer.is_none()&&self.producer_reply.is_none()&&self.producer_refusal.is_none()&&self.action.is_none()&&self.grant.is_none()&&self.actual.is_none()&&self.performed.is_none()&&self.partial_work.is_none()&&self.work_claim.is_none()&&self.work_proof.is_none()&&self.work_action.is_none()&&self.allocation.is_none()&&self.outcome.is_none()&&self.child.is_none()&&self.grant_refusal.is_none()&&self.effect_refusal.is_none()&&self.work_refusal.is_none()&&self.work_reporting.is_none()&&self.work_overrun.is_none()&&self.receipt_refusal.is_none()&&self.receipt_primary.is_empty()}
 pub fn has_pending_recovery(&self)->bool{!self.has_no_retained_custody()}
 pub fn pending_recovery(&mut self)->Option<&mut Self>{if self.has_pending_recovery(){Some(self)}else{None}}
 /// 📏️ Checks the exact demand retained before the original grant callback.
 /// 📏️ Borrows the retained original demand without inspecting the source.
 pub fn pending_demand(&self)->Option<RetirementDemand>{self.has_pending_recovery().then_some(self.demand)}
 /// 🧾️ Observes the same demand and Work ceiling already frozen before Source callbacks.
 pub fn pending_request(&self)->Option<(RetirementDemand,u64)>{self.has_pending_recovery().then_some(self.maximum_work).flatten().map(|work|(self.demand,work))}

 pub fn matches_demand(&self,demand:RetirementDemand)->bool{self.demand==demand}
 /// 📏️ Returns the actual effect marker retained through an unwind.
 pub fn actual(&self)->Option<usize>{self.actual}
 /// 🧾️ Reads the submitted physical receipt without replacing the original child progress.
 pub fn construction_progress(&self)->Option<RetainedCloneProgress>{self.action.as_ref().and_then(OriginalConstructionAction::progress)}
 /// 🧾️ Observes only the actual recorded construction verdict while the frame owns its action.
 pub fn recorded_receipt_status(&self)->Option<OriginalConstructionAcceptStatus>{self.action.as_ref().and_then(OriginalConstructionAction::recorded_accept_status)}
 /// 🪪️ Lends the same validated granted construction action before the original producer enters.
 pub fn with_granted_construction<H:NativeReceivingEffectHost+?Sized,R>(&self,control:&mut H,operation:impl FnOnce(&OriginalConstructionActionWitness<'_>)->R)->Result<R,ValueError>{
  if self.phase!=NativeReceivingEffectPhase::EffectStarted||!self.same_work(control){return Err(Self::invalid())}
  let binding=control.original_work().binding_identity()?;if self.binding!=Some(binding){return Err(Self::invalid())}
  let action=self.action.as_ref().ok_or_else(Self::invalid)?;let loan=control.construction()?;let witness=loan.witness(action)?;
  if witness.phase()!=OriginalConstructionPhase::Granted||Some(witness.grant().ok_or_else(Self::invalid)?)!=self.grant||witness.work_binding()!=binding||witness.source_turn().is_some_and(|source|Some(source)!=binding.source_turn()){return Err(Self::invalid())}
  Ok(operation(&witness))
 }
 /// 🧬️ Copies only evidence made from this frame's validated actual granted action.
 pub fn construction_binding<H:NativeReceivingEffectHost+?Sized>(&self,control:&mut H)->Result<NativeReceivingConstructionBinding,ValueError>{let work_action=self.work_action.ok_or_else(Self::invalid)?;self.with_granted_construction(control,|witness|NativeReceivingConstructionBinding{action:witness.identity(),work:witness.work_binding(),work_action,source:witness.source_turn(),grant:witness.grant().expect("granted witness")})}
 /// ⏱️ Borrows the actual retained child work without transferring its outcome.
 pub fn child_work(&self)->Option<u128>{self.child.as_ref().map(|_|self.recorded_work())}
 /// 🧾️ Borrows the original finished Work proof without transferring or recreating it.
 pub fn finished_work_proof(&self)->Option<&OriginalWorkActionProof>{self.work_proof.as_ref().filter(|proof|proof.is_finished())}
 /// 🔐️ Checks the actual retained Work binding against a paid effect.
 pub fn matches_work_effect(&self,effect:&RetainedAllocationEffect<'_>)->bool{self.binding.is_some_and(|binding|binding.matches_effect(effect))}
 /// 🧾️ Reports whether the original work reservation has already settled.
 pub fn work_is_settled(&self)->bool{self.work_settled}
 /// 🔁️ Reports whether the original work settlement still needs its issuer.
 pub fn work_commit_is_pending(&self)->bool{self.work_commit_pending}
 /// 🧮️ Transfers a retained child work observation to its original caller only once.
