 pub fn recover_allocation_callback<H:NativeReceivingEffectHost+?Sized>(&mut self,control:&mut H)->Result<bool,ValueError>{if self.child.is_some()&&!self.valid_work_proof(control)?{return Err(Self::invalid())}if self.phase!=NativeReceivingEffectPhase::EffectStarted||!self.same_recipient(control){return Err(Self::invalid())}let state=self.allocation.as_mut().ok_or_else(Self::invalid)?;control.recover_allocation_callback(state)}
 pub fn same_recipient<H:NativeReceivingEffectHost+?Sized>(&self,control:&mut H)->bool{Self::recipient(control).is_ok_and(|recipient|Some(recipient.identity())==self.recipient)}
 /// 🛟️ Cleanup observes cancellation while retaining permission to drain its original owner.
 pub fn quote_retirement<H:NativeReceivingEffectHost+?Sized>(&mut self,control:&mut H,demand:RetirementDemand,maximum_work:u64)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::Empty||self.ack_identity.is_some()||!control.has_retirement(){return Err(Self::invalid())}self.retiring=true;self.maximum_work=Some(maximum_work);control.observe_retirement()?;self.work_issuer=control.work_issuer();let identity=control.begin_construction(demand,&mut self.action)?;self.recipient=Some(identity);let mut recipient=Self::recipient(control)?;self.demand=demand;self.phase=NativeReceivingEffectPhase::GrantStarted;recipient.quote(self.action.as_mut().ok_or_else(Self::invalid)?)?;self.recover_grant(control)?;Ok(())}
 pub fn same_work<H:NativeReceivingEffectHost+?Sized>(&self,control:&H)->bool{self.work_issuer.is_some()&&self.work_issuer==control.work_issuer()}
