 pub fn finish_child_work_for_payout<H:NativeReceivingEffectHost+?Sized>(&mut self,control:&mut H)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::ReceiptStarted||self.action.as_ref().and_then(|action|action.recorded_accept_status())!=Some(semio_framework_value_control_contract::OriginalConstructionAcceptStatus::Refused)||!self.same_recipient(control)||!self.valid_work_proof(control)?||self.work_proof.as_ref().is_none_or(|proof|proof.is_finished()){return Err(Self::invalid())}control.original_work().finish_retained(&mut self.work_proof,&mut self.work_action)}
 fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native receiving frame requires its original recipient and callback phase")}
 pub fn recipient<H:NativeReceivingEffectHost+?Sized>(control:&mut H)->Result<OriginalConstructionLoan<'_>,ValueError>{control.construction()}
 /// 🎟️ Retains the callback boundary before requesting the original physical grant.
 pub fn quote<H:NativeReceivingEffectHost+?Sized>(&mut self,control:&mut H,demand:RetirementDemand)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::Empty||self.ack_identity.is_some(){return Err(Self::invalid())}if self.action.is_none(){control.checkpoint()?;self.work_issuer=control.work_issuer();let identity=control.begin_construction(demand,&mut self.action)?;self.recipient=Some(identity)}let binding=control.original_work().binding_identity()?;if self.binding.is_some_and(|original|original!=binding){return Err(Self::invalid())}let mut recipient=Self::recipient(control)?;let action=self.action.as_ref().ok_or_else(Self::invalid)?;if action.demand()!=demand||action.phase()!=OriginalConstructionPhase::Fresh||action.work_binding()!=binding||!recipient.validates_action(action)?||self.recipient.is_some_and(|identity|identity!=recipient.identity()){return Err(Self::invalid())}self.recipient=Some(recipient.identity());self.demand=demand;self.phase=NativeReceivingEffectPhase::GrantStarted;recipient.quote(self.action.as_mut().ok_or_else(Self::invalid)?)?;self.recover_grant(control)?;Ok(())}
 /// 🪪️ Resolves a grant callback interrupted after its original recipient started it.
 pub fn recover_grant<H:NativeReceivingEffectHost+?Sized>(&mut self,control:&mut H)->Result<bool,ValueError>{if self.phase!=NativeReceivingEffectPhase::GrantStarted{return Err(Self::invalid())}let mut recipient=Self::recipient(control)?;if Some(recipient.identity())!=self.recipient{return Err(Self::invalid())}let action=self.action.as_mut().ok_or_else(Self::invalid)?;let Some(reply)=recipient.recover_grant(action)?else{return Ok(false)};match reply{Ok(grant)=>{self.grant=Some(grant);if retained_clone_grant_admits(grant,self.demand){self.phase=NativeReceivingEffectPhase::Granted}else{recipient.cancel(action,false,Default::default(),None)?;self.phase=NativeReceivingEffectPhase::Settled}},Err(error)=>{*self.grant_refusal=Some(error);self.phase=NativeReceivingEffectPhase::Settled}}Ok(true)}
