 pub fn effect_admitted<H:NativeReceivingEffectHost+?Sized>(&self,control:&mut H)->Result<RetainedCloneGrant,ValueError>{if !self.same_work(control)||self.work_action.is_none()||self.work_action!=control.original_work().action_identity()||!control.has_pending_work()||control.work_quote_pending()||Self::recipient(control).ok().is_none_or(|recipient|Some(recipient.identity())!=self.recipient){return Err(Self::invalid())}control.original_work().validate_action_source(self.work_action)?;self.grant.ok_or_else(Self::invalid)}
