 /// 🧵️ Lends the actual decoder only after its original allocation quote resides in this frame.
 pub fn effect_controlled<H:NativeReceivingEffectHost+?Sized>(&mut self,control:&mut H,operation:impl FnOnce(&mut H,&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome<RetainedCloneStep,E>)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::Granted{return Err(Self::invalid())}self.effect_admitted(control)?;self.phase=NativeReceivingEffectPhase::EffectStarted;match control.prepare_allocation_effect(self.demand.capacity_bytes,&self.actual,&mut self.allocation,!self.retiring){semio_framework_value_native_outcome::NativeDecodeAllocationAdmission::Admitted=>{},semio_framework_value_native_outcome::NativeDecodeAllocationAdmission::Refused(outcome)=>{*self.outcome=Some(outcome);self.phase=NativeReceivingEffectPhase::EffectFinished;return Ok(())},semio_framework_value_native_outcome::NativeDecodeAllocationAdmission::Pending=>return Ok(())}self.resume_effect_controlled(control,operation)}
