 /// 🔁️ Retains the resolved allocation outcome before any construction receipt callback.
 pub fn finish_allocation<H:NativeReceivingEffectHost+?Sized>(&mut self,control:&mut H)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::EffectStarted||!self.same_recipient(control)||self.outcome.is_some()||(self.child.is_some()&&!self.valid_work_proof(control)?){return Err(Self::invalid())}let state=self.allocation.as_mut().ok_or_else(Self::invalid)?;if state.operation_started()&&self.child.is_none(){return Err(Self::invalid())}if let Some(turn)=self.child.as_ref(){let progress=match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.receiving_progress()};if self.actual.is_none()&&progress.retained_capacity_bytes!=0{return Err(Self::invalid())}if self.effect_refusal.is_none(){*self.effect_refusal=marker_mismatch(self.actual,progress)}}if !matches!(state.phase(),semio_framework_value_native_outcome::NativeDecodeAllocationPhase::Settled|semio_framework_value_native_outcome::NativeDecodeAllocationPhase::QuoteRefused){if !control.settle_allocation_progress(state,self.actual)?{return Ok(())}}let state=self.allocation.take().ok_or_else(Self::invalid)?;match state.into_outcome(){Ok(outcome)=>*self.outcome=Some(outcome),Err(state)=>{*self.allocation=Some(state);return Err(Self::invalid())}}self.phase=NativeReceivingEffectPhase::EffectFinished;Ok(())}
 /// 🧾️ Commits the original held work and retains any independent refusal in this frame.
