 pub fn cancel_unstarted<H:NativeReceivingEffectHost+?Sized>(&mut self,control:&mut H)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::Granted{return Err(Self::invalid())}if self.work_action.is_some(){if !self.same_work(control){return Err(Self::invalid())}control.original_work().cancel(&mut self.work_action)?}let mut recipient=Self::recipient(control)?;if Some(recipient.identity())!=self.recipient{return Err(Self::invalid())}recipient.cancel(self.action.as_mut().ok_or_else(Self::invalid)?,false,Default::default(),None)?;self.phase=NativeReceivingEffectPhase::Settled;Ok(())}
 /// 🧾️ Submits retained actual progress once under the unchanged original construction recipient.
 pub fn receipt<H:NativeReceivingEffectHost+?Sized>(&mut self,control:&mut H)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::EffectFinished||self.work_commit_pending||(self.child.is_some()&&!self.valid_work_proof(control)?){return Err(Self::invalid())}if self.child.is_none(){self.cancel_unperformed_work(control)?}let mut recipient=Self::recipient(control)?;if Some(recipient.identity())!=self.recipient{return Err(Self::invalid())}let action=self.action.as_mut().ok_or_else(Self::invalid)?;let Some(turn)=self.child.as_ref()else{if self.actual.is_some(){return Err(Self::invalid())}recipient.cancel(action,false,Default::default(),None)?;self.phase=NativeReceivingEffectPhase::Settled;return Ok(())};let progress=match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.receiving_progress()};let grant=self.grant.ok_or_else(Self::invalid)?;let submitted=match self.actual{Some(bytes)=>RetainedCloneProgress{retained_capacity_bytes:bytes,..progress},None if progress.retained_capacity_bytes==0=>progress,None=>return Err(Self::invalid())};if (!progress.fits(grant)||!submitted.fits(grant))&&self.grant_refusal.is_none(){*self.grant_refusal=Some(ValueError::literal(ValueRefusalKind::InvariantViolated,"native child receipt exceeds original grant"))}self.phase=NativeReceivingEffectPhase::ReceiptStarted;if let Err(error)=recipient.post(action,submitted,self.actual){if action.phase()==semio_framework_value_control_contract::OriginalConstructionPhase::Granted{self.phase=NativeReceivingEffectPhase::EffectFinished}return Err(error)}self.recover_receipt(control)?;Ok(())}
 /// 🪪️ Resolves an interrupted receipt without issuing it again or changing its owner.
